//! `whatsapp_idb_leveldb_diff` — Phase 7.J S2.5 step 2
//!
//! Reads the LevelDB files generated by `whatsapp_idb_cryptokey_diff_gen`
//! for each row and reports:
//!
//! 1. File-level sizes per row (IndexedDB LevelDB dir)
//! 2. Byte-exact diff between row A (aes-ext-true) and row B (aes-ext-false)
//! 3. Byte-exact diff between row C (hmac-ext-true) and row D (hmac-ext-false)
//! 4. Greps for the known key bytes (raw AES key bytes = `aa`*32) in every row's
//!    binary dump. If they appear only in the `aes-ext-*` rows, that suggests
//!    Case 1 (raw key embedded).
//!
//! We deliberately do NOT depend on a LevelDB parser; we read the `.ldb` /
//! `.log` / `.man`-prefixed files as opaque byte streams and grep them with
//! `memchr`. This is intentionally lightweight — we're hunting for a 32-byte
//! needle.
//!
//! Run:
//!   cargo run -p whatsapp_chrome_session_extract --bin whatsapp_idb_leveldb_diff --release

use anyhow::{Context, Result};
use clap::Parser;
use std::path::PathBuf;
use tracing::info;

#[derive(Parser, Debug)]
struct Args {
    /// Manifest produced by `whatsapp_idb_cryptokey_diff_gen`.
    #[arg(long, default_value = "/tmp/idb-diff/manifest.json")]
    manifest: PathBuf,
    /// Grep hex bytes (case-insensitive substring match against each file).
    #[arg(long, default_value = "true")]
    grep_needles: bool,
    /// Pretty-print first N bytes of every ldb file.
    #[arg(long, default_value_t = 256)]
    head_bytes: usize,
}

#[derive(Debug, serde::Deserialize)]
struct Row {
    row: String,
    algo: String,
    extractable: bool,
    key_hex: String,
    key_id: String,
    db_name: String,
    profile_dir: String,
    port: u16,
}

#[derive(Debug, serde::Deserialize)]
struct Manifest {
    rows: Vec<Row>,
}

fn hex_lower(s: &str) -> String {
    s.chars()
        .filter(|c| !c.is_whitespace())
        .collect::<String>()
        .to_lowercase()
}

fn hex_to_bytes(s: &str) -> Vec<u8> {
    let s = hex_lower(s);
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap_or(0))
        .collect()
}

fn find_all(haystack: &[u8], needle: &[u8]) -> Vec<usize> {
    if needle.is_empty() || haystack.len() < needle.len() {
        return Vec::new();
    }
    let mut out = Vec::new();
    let mut i = 0;
    while let Some(pos) = memchr::memmem::find(&haystack[i..], needle) {
        out.push(i + pos);
        if i + pos + needle.len() >= haystack.len() {
            break;
        }
        i = i + pos + 1;
    }
    out
}

fn list_idb_files(profile_user_dir: &std::path::Path) -> Vec<PathBuf> {
    let mut out = Vec::new();
    // Chrome 150 places IndexedDB at <profile>/IndexedDB OR <profile>/Default/IndexedDB
    // depending on --user-data-dir usage. Walk every IndexedDB descendant.
    let idb_root = profile_user_dir.join("IndexedDB");
    if idb_root.is_dir() {
        walk_dir(&idb_root, &mut out);
    }
    let default_idb = profile_user_dir.join("Default").join("IndexedDB");
    if default_idb.is_dir() {
        walk_dir(&default_idb, &mut out);
    }
    out.sort();
    out
}

fn walk_dir(p: &std::path::Path, out: &mut Vec<PathBuf>) {
    if let Ok(rd) = std::fs::read_dir(p) {
        for entry in rd.flatten() {
            let path = entry.path();
            if path.is_dir() {
                walk_dir(&path, out);
            } else {
                out.push(path);
            }
        }
    }
}

/// Read every file under the profile's IndexedDB dir into one big blob,
/// keyed by relative path. Returns (relative-path -> bytes).
fn slurp_profile(profile_root: &std::path::Path) -> std::collections::BTreeMap<String, Vec<u8>> {
    let mut by_path: std::collections::BTreeMap<String, Vec<u8>> =
        std::collections::BTreeMap::new();
    let user_dir = profile_root.join("chrome-user-data");
    for f in list_idb_files(&user_dir) {
        if let Ok(bytes) = std::fs::read(&f) {
            let rel = f
                .strip_prefix(&user_dir)
                .unwrap_or(&f)
                .display()
                .to_string();
            by_path.insert(rel, bytes);
        }
    }
    by_path
}

fn ldb_total(by_path: &std::collections::BTreeMap<String, Vec<u8>>) -> usize {
    by_path
        .iter()
        .filter(|(k, _)| {
            k.ends_with(".ldb") || k.ends_with(".log") || k.starts_with("MANIFEST")
        })
        .map(|(_, v)| v.len())
        .sum()
}

fn filt_ldb_paths(by_path: &std::collections::BTreeMap<String, Vec<u8>>) -> Vec<&String> {
    by_path
        .iter()
        .filter(|(k, _)| k.ends_with(".ldb") || k.ends_with(".log") || k.starts_with("MANIFEST"))
        .map(|(k, _)| k)
        .collect()
}

fn diff_slurps(
    a: &std::collections::BTreeMap<String, Vec<u8>>,
    b: &std::collections::BTreeMap<String, Vec<u8>>,
) -> Vec<String> {
    let mut lines = Vec::new();
    let mut all_keys: std::collections::BTreeSet<&String> =
        a.keys().chain(b.keys()).collect();
    for k in &all_keys {
        let va = a.get(*k);
        let vb = b.get(*k);
        match (va, vb) {
            (Some(va), Some(vb)) => {
                if va.len() != vb.len() {
                    lines.push(format!(
                        "  SIZE DIFF {} : {}B vs {}B",
                        k,
                        va.len(),
                        vb.len()
                    ));
                } else if va != vb {
                    let diffs: usize = va
                        .iter()
                        .zip(vb.iter())
                        .filter(|(x, y)| x != y)
                        .count();
                    lines.push(format!(
                        "  BYTE DIFF {} : same len {}B, {} byte(s) differ",
                        k,
                        va.len(),
                        diffs
                    ));
                }
            }
            (Some(va), None) => {
                lines.push(format!("  ONLY-IN-A {} : {}B", k, va.len()));
            }
            (None, Some(vb)) => {
                lines.push(format!("  ONLY-IN-B {} : {}B", k, vb.len()));
            }
            _ => {}
        }
    }
    lines
}

fn grep_blob(by_path: &std::collections::BTreeMap<String, Vec<u8>>, needle: &[u8]) -> Vec<(String, usize, Vec<usize>)> {
    let mut hits = Vec::new();
    for (k, v) in by_path {
        let positions = find_all(v, needle);
        if !positions.is_empty() {
            hits.push((k.clone(), v.len(), positions));
        }
    }
    hits
}

#[tokio::main]
async fn main() -> Result<()> {
    let args = Args::parse();
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .with_writer(std::io::stderr)
        .init();

    let manifest_bytes = std::fs::read(&args.manifest)
        .with_context(|| format!("manifest not found: {}", args.manifest.display()))?;
    let manifest: Manifest =
        serde_json::from_slice(&manifest_bytes).context("parse manifest")?;
    info!("loaded manifest with {} rows", manifest.rows.len());

    if manifest.rows.len() != 4 {
        anyhow::bail!(
            "expected 4 rows in design matrix, got {}",
            manifest.rows.len()
        );
    }

    // Map row name -> slurped LDB files
    let mut slurps: std::collections::BTreeMap<String, std::collections::BTreeMap<String, Vec<u8>>> =
        std::collections::BTreeMap::new();
    for row in &manifest.rows {
        let profile_root = PathBuf::from(&row.profile_dir);
        let s = slurp_profile(&profile_root);
        let total = ldb_total(&s);
        info!("row={} db={} profile={} total LDB bytes={}",
              row.row, row.db_name, profile_root.display(), total);
        println!(
            "row={:20} algo={:6} ext={:5} db={:25} ldb+log+manifest_bytes={}",
            row.row,
            row.algo,
            row.extractable,
            row.db_name,
            total
        );
        for p in filt_ldb_paths(&s) {
            println!("    {}", p);
        }
        slurps.insert(row.row.clone(), s);
    }
    println!();

    // ---- Pairwise diffs ----
    println!("== Pairwise diff (AES extractable=true vs false) ==");
    let diff_lines = diff_slurps(
        slurps.get("aes-ext-true").unwrap(),
        slurps.get("aes-ext-false").unwrap(),
    );
    if diff_lines.is_empty() {
        println!("  IDENTICAL across every IndexedDB file.");
    } else {
        for l in &diff_lines {
            println!("{l}");
        }
    }
    println!();

    println!("== Pairwise diff (HMAC extractable=true vs false) ==");
    let diff_lines = diff_slurps(
        slurps.get("hmac-ext-true").unwrap(),
        slurps.get("hmac-ext-false").unwrap(),
    );
    if diff_lines.is_empty() {
        println!("  IDENTICAL across every IndexedDB file.");
    } else {
        for l in &diff_lines {
            println!("{l}");
        }
    }
    println!();

    // ---- Grep for known key bytes ----
    if args.grep_needles {
        println!("== Grep for known raw key bytes (Case-1 needle test) ==");
        for row in &manifest.rows {
            let needle = hex_to_bytes(&row.key_hex);
            let s = slurps.get(&row.row).unwrap();
            let hits = grep_blob(s, &needle);
            let total_occurrences: usize = hits.iter().map(|h| h.2.len()).sum();
            if total_occurrences == 0 {
                println!(
                    "  row={:20} needle={}... NOT FOUND in any IndexedDB file",
                    row.row,
                    hex_lower(&row.key_hex).chars().take(8).collect::<String>()
                );
            } else {
                println!(
                    "  row={:20} needle={}... FOUND {} total occurrence(s) across {} file(s)",
                    row.row,
                    hex_lower(&row.key_hex).chars().take(8).collect::<String>(),
                    total_occurrences,
                    hits.len()
                );
                for (path, file_len, positions) in &hits {
                    println!("    {}: file {}B, hits at offsets {:?}", path, file_len, positions);
                }
            }
        }
        println!();
    }

    // ---- Head-bytes dump for the AES rows so we can eyeball structure ----
    println!(
        "== First {} bytes of each AES row's .ldb / .log / MANIFEST (hex) ==",
        args.head_bytes
    );
    for row in &manifest.rows {
        if !row.row.starts_with("aes") {
            continue;
        }
        let s = slurps.get(&row.row).unwrap();
        for (path, bytes) in s {
            if !path.ends_with(".ldb") && !path.ends_with(".log") && !path.starts_with("MANIFEST") {
                continue;
            }
            let take = bytes.len().min(args.head_bytes);
            let head_hex: String = bytes[..take]
                .iter()
                .map(|b| format!("{:02x}", b))
                .collect();
            // Print in 64-char chunks
            println!("  {} ({}B total)", path, bytes.len());
            for chunk in head_hex
                .as_bytes()
                .chunks(64)
                .map(|c| std::str::from_utf8(c).unwrap_or(""))
            {
                println!("    {chunk}");
            }
            println!();
        }
    }

    Ok(())
}
